import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

Map<String, Object> searchableContent = Map.of("placeholder_text", "Search products",
        "product", Map.of("enabled", true, "display_heading", "Product", "excluded", List.of(Map.of("id", 4, "name", "Gift Card"))),
        "product_categories", Map.of("enabled", true, "hide_parent_category", true, "display_heading", "Product Categories",
                "excluded", List.of(Map.of("id", 16, "name", "Clearance"))),
        "blog", Map.of("enabled", true, "display_heading", "Blog Posts", "excluded", List.of(Map.of("id", 13, "name", "Store News"))),
        "other_pages", Map.of("enabled", true, "display_heading", "Other Pages", "excluded", List.of(Map.of("id", 4, "name", "Home - Copy"))));
Map<String, Object> searchFields = Map.of("match_keywords_exactly", false, "match_full_sentences", false, "fields", List.of(
        Map.of("field", "title", "priority", 1), Map.of("field", "tags", "priority", 2), Map.of("field", "category", "priority", 3),
        Map.of("field", "description", "priority", 4), Map.of("field", "sku", "priority", 5), Map.of("field", "brand", "priority", 6)));
Map<String, Object> synonyms = Map.of("groups", List.of(Map.of("keywords", List.of("mobile", "phone", "telephone")),
        Map.of("keywords", List.of("shoe", "footwear", "sneaker"))));
ApiResponse response = client.searchSettings().putSearchSettings(Map.of("search_settings",
        Map.of("searchable_content", searchableContent, "search_fields", searchFields, "synonyms", synonyms)));
Map<?, ?> settings = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("search_settings");
System.out.println(((Map<?, ?>) settings.get("searchable_content")).get("placeholder_text"));

